ImuFilterNodeDiagnostics::ImuFilterNodeDiagnostics(
  rclcpp::Node & node, ImuFilterNodeEngine & engine)
: node_(node),
  engine_(engine)
{
  group_ = node_.create_callback_group(rclcpp::CallbackGroupType::MutuallyExclusive);

  pub_ = node_.create_publisher<diagnostic_msgs::msg::DiagnosticArray>(
    names::kDiagnosticsTopic, rclcpp::QoS(names::kDiagnosticsQosDepth));

  timer_ = binding::create_timer(
    node_, clock_, std::chrono::seconds(names::kDiagnosticsPeriodS),
    std::bind(&ImuFilterNodeDiagnostics::drain, this), group_);
}

void ImuFilterNodeDiagnostics::drain()
{
  diagnostic_msgs::msg::DiagnosticArray array;
  std::vector<Occurrence> occurrences;

  for (const auto & entry : engine_.take_diagnostics()) {
    array.status.push_back(make_status(node_.get_fully_qualified_name(), entry));
    count(occurrences, entry);
  }

  for (const auto & seen : occurrences) {
    log(seen.code, seen.who, seen.count);
  }

  if (!array.status.empty()) {
    array.header.stamp = node_.now();
    pub_->publish(array);
  }
}

void ImuFilterNodeDiagnostics::log(r2d::Code code, const char * who, std::size_t count)
{
  const char * pipeline = who ? who : "";
  if (code == r2d::Code::ERR_RUN_101) {
    RCLCPP_ERROR(
      node_.get_logger(), "%s: %s (pipeline '%s', %zu time(s))", r2d::code_name(code),
      r2d::code_message(code), pipeline, count);
  } else {
    RCLCPP_WARN(
      node_.get_logger(), "%s: %s (pipeline '%s', %zu time(s))", r2d::code_name(code),
      r2d::code_message(code), pipeline, count);
  }
}

